# -*- coding: utf-8 -*-
# domains_it.py - 30 Tech & Computing articles

IT_ARTICLES = {'guidance-cntt-y1': {'lead': 'Hướng dẫn chi tiết từ A-Z lộ trình xây dựng tư duy giải thuật, làm chủ kiến trúc máy tính và kỹ năng lập trình cơ bản, giúp người mới bắt đầu tự tin bước vào thế giới công nghệ phần mềm.', 'overview_p1': 'Ngành Công nghệ thông tin là nền tảng cốt lõi của xã hội số hóa. Ngay từ vạch xuất phát, sinh viên cần hiểu rõ rằng việc học lập trình không đơn thuần là ghi nhớ cú pháp của một ngôn ngữ, mà là rèn luyện năng lực trừu tượng hóa: phân tích một bài toán đời thực thành các bước logic rõ ràng mà máy tính có thể thực thi chính xác. Việc nắm vững cách thức CPU xử lý chỉ lệnh và cách hệ điều hành Linux phân phối tài nguyên sẽ tạo nên lợi thế vượt trội cho bạn trong suốt 4 năm đại học.', 'overview_p2': 'Đối với người mới bắt đầu, sai lầm phổ biến nhất là vội vàng học các framework thời thượng mà bỏ qua kiến thức nền tảng về thuật toán và kiến trúc phần cứng. Lộ trình dưới đây được thiết kế bài bản qua 4 giai đoạn cụ thể, từ việc tiếp cận cú pháp đầu tiên đến khi làm chủ môi trường dòng lệnh, giúp bạn xây dựng nền móng kỹ thuật vững chắc không thể lung lay.', 'career_roles': [('Lập trình viên tập sự (Software Developer Intern)', 'Tham gia viết mã nguồn các module xử lý dữ liệu cơ bản, sửa lỗi cú pháp và viết tài liệu mô tả hàm.'), ('Kỹ thuật viên hệ thống & Mạng cơ sở', 'Cấu hình môi trường làm việc trên máy chủ Linux, thiết lập mạng cục bộ và hỗ trợ xử lý sự cố kết nối.'), ('Cộng tác viên hỗ trợ kỹ thuật (Technical Support)', 'Tiếp nhận phản hồi người dùng, tái hiện lỗi trên môi trường thử nghiệm và phân loại lỗi phần mềm.')], 'stages': [('Giai đoạn 1: Khởi động tư duy giải thuật & Cú pháp lập trình cơ bản với Python', ['Làm quen với các kiểu dữ liệu nguyên thủy (integer, float, string, boolean), toán tử logic và cấu trúc rẽ nhánh điều kiện (if/elif/else).', 'Luyện tập vòng lặp (for, while) và cấu trúc hàm (function) thông qua việc giải 40 bài toán tính toán số học trên nền tảng HackerRank.', 'Cài đặt và cấu hình môi trường phát triển chuyên nghiệp: VS Code, Python 3.12, trình quản lý gói pip và môi trường ảo venv.', 'Thực hiện bài tập lớn đầu tay: Viết một công cụ dòng lệnh (CLI) quản lý chi tiêu cá nhân có lưu trữ dữ liệu vào tệp tin JSON.']), ('Giai đoạn 2: Cấu trúc máy tính, dòng lệnh Linux Bash & Quản lý phiên bản với Git', ['Hiểu rõ kiến trúc máy tính Von Neumann, chu trình nạp-giải mã-thực thi của CPU và cấu trúc tổ chức bộ nhớ (RAM, Cache, Disk).', 'Thành thạo tối thiểu 30 lệnh Bash cơ bản trong terminal Linux (Ubuntu): điều hướng thư mục, quản lý tiến trình, phân quyền tệp (chmod/chown).', 'Thực hành quy trình làm việc với Git: khởi tạo repository, commit có thông điệp chuẩn (Conventional Commits), tạo nhánh (branch) và đẩy mã lên GitHub.', 'Tự xây dựng một script tự động hóa bằng Bash để sao lưu dữ liệu thư mục định kỳ vào kho lưu trữ nén (.tar.gz).']), ('Giai đoạn 3: Cấu trúc dữ liệu tuyến tính & Kỹ năng viết mã sạch (Clean Code)', ['Nắm vững nguyên lý và cách tự cài đặt các cấu trúc dữ liệu tuyến tính: Danh sách liên kết đơn (Singly Linked List), Ngăn xếp (Stack), Hàng đợi (Queue).', 'Hiểu bản chất độ phức tạp thời gian O(n) và không gian bộ nhớ O(1) qua các thuật toán tìm kiếm tuyến tính và sắp xếp chọn/chèn cơ bản.', 'Áp dụng nguyên tắc Clean Code: đặt tên biến có nghĩa, chia nhỏ hàm xử lý đơn nhiệm (Single Responsibility) và viết chú thích kỹ thuật rõ ràng.', 'Hoàn thành mini-project: Trình mô phỏng hàng đợi xử lý tác vụ in ấn văn phòng sử dụng cấu trúc Queue tự cài đặt.']), ('Giai đoạn 4: Đồ án ứng dụng dòng lệnh hoàn chỉnh & Định hình phương pháp tự học', ['Thiết kế kiến trúc ứng dụng dòng lệnh hoàn chỉnh kết hợp xử lý ngoại lệ (Exception Handling) và ghi nhật ký hoạt động (Logging).', 'Rèn luyện kỹ năng đọc hiểu tài liệu kỹ thuật chuẩn tiếng Anh (Python Official Docs, Stack Overflow) và đặt câu hỏi gỡ lỗi (Debugging).', 'Đóng gói dự án cá nhân lên GitHub với tệp README.md chuẩn quốc tế, tài liệu hướng dẫn cài đặt và video demo ngắn.', 'Tự đánh giá năng lực qua bài kiểm tra toàn diện 50 câu trắc nghiệm kiến trúc máy tính và hoàn thành thử thách lập trình trực tiếp 90 phút.'])], 'requirements': ['Máy tính cá nhân tối thiểu RAM 8GB có khả năng cài đặt hệ điều hành Linux hoặc WSL2.', 'Tư duy logic cơ bản và khả năng đọc hiểu tài liệu tiếng Anh trình độ trung cấp (B1 trở lên).', 'Cam kết dành tối thiểu 10 giờ mỗi tuần để thực hành viết mã và giải bài tập trên terminal.']}, 'guidance-cntt-y2': {'lead': 'Hướng dẫn chi tiết từ A-Z lộ trình thiết kế cơ sở dữ liệu quan hệ, phát triển Web Backend hiện đại và làm chủ kiến trúc mạng máy tính dành cho sinh viên công nghệ thông tin.', 'overview_p1': 'Trong bức tranh toàn cảnh của hệ thống công nghệ, tầng Backend đóng vai trò như bộ não xử lý dữ liệu và đảm bảo tính toàn vẹn của mọi giao dịch số. Khi dữ liệu của doanh nghiệp tăng từ hàng ngàn lên hàng triệu bản ghi, việc sở hữu kiến thức chuẩn xác về mô hình quan hệ (Relational Model), chuẩn hóa dữ liệu và cơ chế mạng kết nối giữa máy khách và máy chủ trở thành yếu tố quyết định chất lượng của một kỹ sư công nghệ.', 'overview_p2': 'Để xây dựng được các dịch vụ máy chủ ổn định và chịu tải tốt, bạn cần hiểu sâu bản chất từ các tầng mạng cơ bản đến cách thức hệ quản trị cơ sở dữ liệu lưu trữ các trang dữ liệu trên đĩa cứng. Lộ trình dưới đây trang bị cho bạn tư duy thiết kế API chuẩn mực, tối ưu hóa truy vấn SQL và bảo mật thông tin toàn diện.', 'career_roles': [('Lập trình viên Backend (Junior Backend Developer)', 'Thiết kế cơ sở dữ liệu, xây dựng RESTful API máy chủ và xử lý logic nghiệp vụ giao dịch.'), ('Quản trị viên cơ sở dữ liệu tập sự (Junior DBA)', 'Hỗ trợ thiết kế schema, tối ưu hóa câu lệnh SQL và thiết lập chính sách sao lưu định kỳ.'), ('Kỹ sư mạng cơ sở (Network Support Engineer)', 'Cấu hình địa chỉ IP, phân giải tên miền DNS, giám sát lưu lượng mạng và hỗ trợ hệ thống tường lửa.')], 'stages': [('Giai đoạn 1: Mô hình hóa thực thể ERD & Viết câu truy vấn SQL chuẩn hóa 3NF', ['Học cách phân tích yêu cầu nghiệp vụ thực tế, xác định các thực thể, thuộc tính và mối quan hệ (1-1, 1-N, N-N) để vẽ sơ đồ ERD.', 'Áp dụng các quy tắc chuẩn hóa dữ liệu từ dạng chuẩn 1 (1NF) đến dạng chuẩn 3 (3NF) để loại bỏ tối đa dư thừa dữ liệu và dị thường cập nhật.', 'Thành thạo cú pháp SQL trên PostgreSQL/MySQL: các phép INNER/LEFT/RIGHT JOIN, GROUP BY, HAVING, Subqueries và Window Functions.', 'Thực hành xây dựng cơ sở dữ liệu thương mại điện tử gồm 12 bảng quan hệ có đầy đủ khóa chính (PK), khóa ngoại (FK) và ràng buộc dữ liệu (CHECK/UNIQUE).']), ('Giai đoạn 2: Lập trình RESTful API kiến trúc phân tầng với Node.js & Express', ['Làm chủ mô hình phân tầng Controller - Service - Repository để phân tách rõ ràng giữa giao tiếp HTTP, nghiệp vụ và truy cập cơ sở dữ liệu.', 'Xây dựng dịch vụ RESTful API hoàn chỉnh: định nghĩa đúng các phương thức HTTP (GET, POST, PUT, DELETE) và mã trạng thái chuẩn (200, 201, 400, 404, 500).', 'Triển khai cơ chế xác thực và phân quyền bằng JSON Web Token (JWT), mã hóa mật khẩu một chiều với thuật toán bcrypt.', 'Tích hợp công cụ kiểm thử API tự động với Postman/Newman và viết tài liệu hướng dẫn tích hợp bằng Swagger/OpenAPI.']), ('Giai đoạn 3: Phân tích kiến trúc mạng máy tính & Giao thức truyền thông HTTP/HTTPS', ['Nghiên cứu mô hình 7 tầng OSI và mô hình TCP/IP, hiểu rõ cơ chế bắt tay 3 bước (TCP 3-way handshake) và phân giải địa chỉ DNS.', 'Sử dụng công cụ Wireshark để bắt và phân tích gói tin HTTP/HTTPS, kiểm tra cấu trúc Header, Payload và mã hóa SSL/TLS trong truyền thông mạng.', 'Hiểu rõ cơ chế kết nối đa luồng (Multi-threading), mô hình hướng sự kiện không chặn (Event Loop trong Node.js) và xử lý bất đồng bộ Async/Await.', 'Viết một máy chủ socket cơ bản bằng Node.js để truyền tin nhắn văn bản hai chiều giữa máy khách và máy chủ theo thời gian thực.']), ('Giai đoạn 4: Tối ưu hóa truy vấn Database Indexing & Đồ án Backend hoàn chỉnh', ['Hiểu cấu trúc chỉ mục B-Tree trong cơ sở dữ liệu, phân tích kế hoạch thực thi câu lệnh SQL với lệnh EXPLAIN ANALYZE để phát hiện Table Scan chậm.', 'Áp dụng giao dịch cơ sở dữ liệu (ACID Transactions) để xử lý tình huống trừ tiền trong ví điện tử và đặt chỗ vé xem phim tránh Race Condition.', 'Tích hợp lớp đệm nhớ tạm thời (Caching) với Redis để tăng tốc độ phản hồi cho các điểm cuối API có tần suất truy vấn cao.', 'Triển khai đồ án Backend hoàn chỉnh lên nền tảng đám mây (Render/Railway), kết nối cơ sở dữ liệu đám mây và thực hiện kiểm thử tải với k6.'])], 'requirements': ['Đã hoàn thành kiến thức nền tảng về tư duy lập trình và cấu trúc dữ liệu năm nhất.', 'Cài đặt sẵn hệ quản trị cơ sở dữ liệu PostgreSQL hoặc MySQL Community Server trên máy cục bộ.', 'Kiến thức cơ bản về mô hình mạng và khả năng sử dụng các công cụ kiểm thử API như Postman.']}, 'guidance-cntt-y3': {'lead': 'Hướng dẫn chi tiết từ A-Z lộ trình thiết kế hệ thống phân tán, đóng gói Docker, tự động hóa CI/CD và tối ưu hóa hiệu năng ứng dụng cho sinh viên năm 3.', 'overview_p1': 'Bước vào giai đoạn chuyên sâu, một kỹ sư công nghệ không chỉ dừng lại ở việc viết mã chạy được trên máy cục bộ mà phải giải quyết bài toán vận hành tin cậy trên môi trường phân tán phục vụ hàng chục ngàn người dùng đồng thời. Các khái niệm về container hóa, tự động hóa vòng đời phần mềm (DevOps) và kiến trúc vi dịch vụ (Microservices) là những kỹ năng được các tập đoàn công nghệ săn đón hàng đầu.', 'overview_p2': 'Để làm chủ hệ thống phân tán, sinh viên cần chuyển đổi tư duy từ lập trình đơn lẻ sang tư duy kiến trúc hệ thống: phân tích điểm nghẽn cổ chai (bottleneck), thiết lập cơ chế dự phòng chịu lỗi (fault-tolerance) và tự động hóa quy trình phân phối sản phẩm. Lộ trình dưới đây sẽ đồng hành cùng bạn hiện thực hóa các tiêu chuẩn kỹ thuật doanh nghiệp khắt khe nhất.', 'career_roles': [('Kỹ sư phần mềm thực tập (Software Engineering Intern)', 'Đảm nhận phát triển các module phân tán, tối ưu hóa truy vấn dữ liệu và tích hợp API đối tác.'), ('Kỹ sư DevOps tập sự (Junior DevOps Engineer)', 'Xây dựng và bảo trì đường ống CI/CD, viết Dockerfile và giám sát hạ tầng đám mây.'), ('Kỹ sư kiểm thử tự động (Automation QA Engineer)', 'Viết kịch bản kiểm thử hiệu năng, kiểm thử tải và kiểm tra an ninh hệ thống trong luồng CI.')], 'stages': [('Giai đoạn 1: Đóng gói ứng dụng với Docker & Điều phối đa vùng với Docker Compose', ['Nắm vững nguyên lý hoạt động của Linux cgroups và namespaces làm nền tảng cho công nghệ ảo hóa cấp hệ điều hành (Containerization).', 'Viết tệp Dockerfile tối ưu: áp dụng kỹ thuật Multi-stage build để giảm dung lượng image production từ 1GB xuống dưới 100MB.', 'Sử dụng Docker Compose để điều phối cụm ứng dụng gồm: Web API, Cơ sở dữ liệu PostgreSQL, Cache Redis và Reverse Proxy NGINX.', 'Cấu hình mạng nội bộ (Docker bridge network) và quản lý dữ liệu bền vững thông qua Docker Named Volumes.']), ('Giai đoạn 2: Tự động hóa đường ống CI/CD với GitHub Actions & Kiểm thử liên tục', ['Hiểu rõ triết lý Tích hợp liên tục (Continuous Integration) và Phân phối liên tục (Continuous Delivery) trong chu trình phát triển Agile.', 'Viết workflow tự động trên GitHub Actions: tự động chạy kiểm tra định dạng mã nguồn (Linter), kiểm thử đơn vị (Unit Tests) và kiểm thử độ phủ (Coverage).', 'Cấu hình bước tự động build Docker image, gắn thẻ phiên bản semantic (v1.0.0) và đẩy lên kho lưu trữ Docker Hub hoặc GitHub Packages.', 'Thiết lập cơ chế thông báo tự động kết quả kiểm thử và trạng thái build về kênh làm việc Slack hoặc Discord của nhóm dự án.']), ('Giai đoạn 3: Kiến trúc Microservices, giao tiếp bất đồng bộ qua Message Queue & Redis', ['Nghiên cứu nguyên lý phân rã hệ thống nguyên khối (Monolith) thành các dịch vụ độc lập theo miền nghiệp vụ (Domain-Driven Design).', 'Hiện thực hóa giao tiếp bất đồng bộ giữa các dịch vụ bằng RabbitMQ: cơ chế Producer-Consumer, định tuyến thông điệp Exchange và hàng đợi Dead-letter.', 'Áp dụng mẫu thiết kế Saga để quản lý giao dịch phân tán giữa các vi dịch vụ mà không làm mất tính nhất quán dữ liệu.', 'Xây dựng dịch vụ Caching nâng cao với Redis: chiến lược Cache-Aside, xử lý triệt để hiện tượng Cache Avalanche và Cache Penetration.']), ('Giai đoạn 4: Giám sát hệ thống với Prometheus, Grafana & Kiểm thử tải High-Concurrency', ['Tích hợp thư viện thu thập số liệu (Metrics) vào ứng dụng máy chủ để theo dõi thông số: Request per Second (RPS), độ trễ P95/P99 và tỷ lệ lỗi HTTP 5xx.', 'Cài đặt và thiết lập Dashboard giám sát trực quan trên Grafana kết nối nguồn dữ liệu Prometheus để cảnh báo tức thời khi hệ thống bị quá tải.', 'Thực hiện kiểm thử tải áp lực cao (Stress Testing) bằng công cụ k6: giả lập 5,000 người dùng đồng thời và phân tích biểu đồ suy thoái hiệu năng.', 'Hoàn thành báo cáo đánh giá kiến trúc hệ thống và chiến lược mở rộng theo chiều ngang (Horizontal Auto-scaling).'])], 'requirements': ['Đã nắm vững kỹ năng phát triển Web Backend và thiết kế cơ sở dữ liệu quan hệ.', 'Máy tính cài đặt Docker Desktop hoặc Docker Engine trên môi trường Linux.', 'Tài khoản GitHub cá nhân và kiến thức về quy trình làm việc theo nhánh Git Flow.']}, 'guidance-cntt-y4': {'lead': 'Hướng dẫn chi tiết từ A-Z lộ trình hoàn thiện đồ án tốt nghiệp công nghệ thông tin xuất sắc, chuẩn bị portfolio chuyên môn chuẩn quốc tế và chinh phục nhà tuyển dụng hàng đầu.', 'overview_p1': 'Năm thứ tư là thời điểm sinh viên tổng hòa mọi kiến thức và kỹ năng đã tích lũy trong suốt quãng đời sinh viên để chuyển hóa thành giá trị thực tế cho ngành công nghiệp. Một đồ án tốt nghiệp chất lượng không chỉ là một bài tập lớn trên lớp mà phải thể hiện được năng lực giải quyết một bài toán nghiệp vụ cụ thể, có kiến trúc rõ ràng, tính sẵn sàng cao và tuân thủ các chuẩn mực an toàn thông tin.', 'overview_p2': 'Thị trường tuyển dụng kỹ sư công nghệ luôn tìm kiếm những ứng viên không chỉ vững về kỹ thuật mà còn có tư duy phản biện, kỹ năng trình bày mạch lạc và thái độ làm việc chuyên nghiệp. Lộ trình 4 giai đoạn dưới đây được đúc kết từ kinh nghiệm thực tiễn giúp bạn tự tin bảo vệ khóa luận xuất sắc và bước thẳng vào các vị trí Fresher/Junior chất lượng cao.', 'career_roles': [('Kỹ sư phần mềm chính thức (Fresher/Junior Software Engineer)', 'Chịu trách nhiệm phát triển độc lập các tính năng phức tạp, tham gia thiết kế module và bảo trì hệ thống production.'), ('Kỹ sư giải pháp đám mây (Cloud Solutions Engineer)', 'Triển khai hạ tầng trên AWS/GCP, tối ưu chi phí vận hành và đảm bảo tính sẵn sàng cao của hệ thống.'), ('Kỹ sư phân tích dữ liệu & Hệ thống (Data/Systems Engineer)', 'Xây dựng luồng dữ liệu tự động, chuẩn hóa dữ liệu doanh nghiệp và phân tích hiệu suất hệ thống.')], 'stages': [('Giai đoạn 1: Lựa chọn đề tài thực tiễn, phân tích kiến trúc hệ thống & Lập kế hoạch', ['Lựa chọn đề tài đồ án tốt nghiệp gắn liền với bài toán thực tiễn của doanh nghiệp hoặc xu hướng công nghệ mới (AI Integration, IoT, Fintech).', 'Lập tài liệu đặc tả yêu cầu phần mềm chi tiết (SRS) bao gồm sơ đồ Use Case, luồng người dùng (User Flow) và ma trận truy xuất nguồn gốc (Traceability Matrix).', 'Thiết kế kiến trúc hệ thống tổng thể theo chuẩn C4 Model (Context, Container, Component, Code) và lựa chọn Tech Stack phù hợp.', 'Lập kế hoạch triển khai dự án theo phương pháp Agile/Scrum: chia sprint 2 tuần, thiết lập bảng Kanban trên Jira và xác định các mốc bàn giao.']), ('Giai đoạn 2: Hiện thực hóa mã nguồn chất lượng cao, kiểm thử tự động & Tinh chỉnh bảo mật', ['Viết mã nguồn tuân thủ nghiêm ngặt các nguyên lý SOLID, mẫu thiết kế hướng đối tượng (Design Patterns) và chuẩn Clean Architecture.', 'Đạt tỷ lệ bao phủ kiểm thử đơn vị (Unit Test Coverage) tối thiểu 75% cho các tầng xử lý nghiệp vụ cốt lõi bằng Jest hoặc Pytest.', 'Rà soát và khắc phục các lỗ hổng bảo mật phổ biến theo danh mục OWASP Top 10: chống SQL Injection, XSS, CSRF và rò rỉ dữ liệu nhạy cảm.', 'Tối ưu hóa mã nguồn: loại bỏ các câu truy vấn N+1, tối ưu thuật toán xử lý dữ liệu lớn và áp dụng nén tài nguyên.']), ('Giai đoạn 3: Triển khai môi trường Production Cloud, hoàn thiện báo cáo & Slide bảo vệ', ['Triển khai ứng dụng hoàn chỉnh lên hạ tầng đám mây (AWS EC2, ECS hoặc GCP Cloud Run) với tên miền riêng và chứng chỉ SSL/TLS bảo mật.', 'Viết báo cáo đồ án tốt nghiệp theo cấu trúc chuẩn học thuật: tổng quan bài toán, cơ sở lý thuyết, phân tích thiết kế, kết quả thử nghiệm và hướng phát triển.', 'Thiết kế slide thuyết trình trực quan, cô đọng: tập trung vào tính mới của giải pháp, sơ đồ kiến trúc và số liệu đo lường hiệu năng thực nghiệm.', 'Thực hiện quay video demo kịch bản hoạt động của hệ thống từ góc nhìn người dùng thực tế để phục vụ hội đồng chấm đồ án.']), ('Giai đoạn 4: Xây dựng Portfolio cá nhân, luyện phỏng vấn kỹ thuật & Gia nhập doanh nghiệp', ['Xây dựng trang Portfolio cá nhân chuyên nghiệp giới thiệu các dự án nổi bật, liên kết kho mã nguồn GitHub và đường dẫn demo trực tiếp.', 'Rèn luyện kỹ năng phỏng vấn cấu trúc dữ liệu và giải thuật (LeetCode Medium) và giải thích tư duy kiến trúc hệ thống (System Design).', 'Chuẩn bị kỹ năng trả lời phỏng vấn hành vi (Behavioral Interview) theo phương pháp STAR (Situation, Task, Action, Result).', 'Hoàn thiện hồ sơ CV kỹ thuật và tham gia ứng tuyển vào các chương trình Fresher/Junior tại các doanh nghiệp đối tác uy tín trên UniHub.'])], 'requirements': ['Tích lũy đầy đủ tín chỉ chuyên ngành và đã hoàn thành kỳ thực tập doanh nghiệp (Internship).', 'Có ít nhất 2 dự án cá nhân hoặc dự án nhóm hoàn chỉnh có mã nguồn lưu trữ trên GitHub.', 'Kỹ năng thuyết trình tự tin và khả năng phản biện giải pháp kỹ thuật trước hội đồng.']}, 'guidance-khmt-y1': {'lead': 'Hướng dẫn chi tiết từ A-Z lộ trình làm chủ cơ sở toán học rời rạc, cấu trúc dữ liệu kinh điển và phân tích độ phức tạp thuật toán dành cho sinh viên khoa học máy tính.', 'overview_p1': 'Khoa học máy tính là nền tảng học thuật của toàn bộ ngành công nghệ tính toán. Khác với lập trình ứng dụng thông thường, khoa học máy tính đào sâu vào bản chất toán học của thông tin và các giới hạn của khả năng tính toán. Năm thứ nhất là giai đoạn vàng để sinh viên rèn luyện tư duy logic toán học chặt chẽ, hiểu rõ cách biểu diễn mệnh đề, lý thuyết đồ thị sơ cấp và phương pháp phân tích độ phức tạp tiệm cận của thuật toán.', 'overview_p2': 'Nhiều sinh viên gặp khó khăn vì cảm thấy toán rời rạc quá trừu tượng và tách rời với việc viết mã lệnh. Lộ trình dưới đây sẽ giúp bạn liên kết trực tiếp giữa các định lý toán học và việc hiện thực hóa các cấu trúc dữ liệu bằng C++ và Python, biến lý thuyết thành công cụ giải quyết bài toán thực tế đầy sức mạnh.', 'career_roles': [('Lập trình viên thuật toán tập sự (Algorithm Developer Intern)', 'Hiện thực hóa các cấu trúc dữ liệu và giải quyết các bài toán tối ưu hóa trong phần mềm mô phỏng.'), ('Trợ lý nghiên cứu tính toán (Computing Research Assistant)', 'Hỗ trợ đo lường chi phí bộ nhớ, thời gian thực thi của thuật toán và thực hiện mô phỏng số.'), ('Cộng tác viên lập trình thi đấu (Competitive Programmer)', 'Luyện tập giải các bài toán thuật toán nâng cao trên Codeforces và chuẩn bị cho kỳ thi ICPC.')], 'stages': [('Giai đoạn 1: Toán học rời rạc, lý thuyết tập hợp & Đại số Boole', ['Nắm vững logic mệnh đề, logic vị từ, các phép toán chân trị và phương pháp chứng minh quy nạp toán học (Mathematical Induction).', 'Học lý thuyết tập hợp, quan hệ tương đương, thứ tự bộ phận và các nguyên lý đếm cơ bản (nguyên lý Dirichlet, quy tắc cộng và nhân).', 'Hiểu bản chất đại số Boole, cổng logic cơ bản (AND, OR, NOT, XOR) và cách rút gọn biểu thức logic bằng bản đồ Karnaugh.', 'Áp dụng đại số Boole để viết chương trình kiểm tra tính đúng đắn của các biểu thức logic phức tạp trong ngôn ngữ C++.']), ('Giai đoạn 2: Phân tích độ phức tạp tiệm cận Big-O & Kỹ thuật lập trình C++ căn bản', ['Làm chủ khái niệm độ phức tạp thời gian và không gian bộ nhớ: ký hiệu Big-O, Big-Omega và Big-Theta.', 'Phân tích độ phức tạp của các đoạn mã lặp lồng nhau, giải hệ thức truy hồi bằng Định lý thợ (Master Theorem) cho giải thuật đệ quy.', 'Thành thạo kỹ thuật lập trình C++ hiện đại: quản lý bộ nhớ thủ công với con trỏ (pointers), tham chiếu (references) và cấp phát động (new/delete).', 'Thực hành giải và tối ưu 50 bài tập thuật toán cơ bản trên Codeforces/LeetCode từ O(n^2) xuống O(n log n).']), ('Giai đoạn 3: Cấu trúc dữ liệu kinh điển & Kỹ thuật đệ quy quay lui', ['Tự tay hiện thực hóa các cấu trúc dữ liệu cốt lõi bằng C++: Mảng động, Danh sách liên kết kép, Hàng đợi ưu tiên (Priority Queue với Heap).', 'Hiểu sâu cơ chế ngăn xếp gọi hàm (Call Stack) trong đệ quy và kỹ thuật đệ quy đuôi (Tail Recursion) để tối ưu bộ nhớ.', 'Áp dụng thuật toán quay lui (Backtracking) để giải các bài toán kinh điển: bài toán N quân hậu, sinh hoán vị và giải câu đố Sudoku.', 'Đo lường thời gian thực thi thực tế của các cấu trúc dữ liệu bằng thư viện chrono của C++ và vẽ biểu đồ so sánh với lý thuyết.']), ('Giai đoạn 4: Cây nhị phân tìm kiếm & Đồ án phân tích thuật toán ứng dụng', ['Nắm vững nguyên lý hoạt động của Cây nhị phân tìm kiếm (Binary Search Tree) và cơ chế tự cân bằng của Cây AVL.', 'Hiện thực hóa các phép duyệt cây: Duyệt tiền thứ tự (Pre-order), trung thứ tự (In-order), hậu thứ tự (Post-order) và theo mức (BFS).', 'Xây dựng ứng dụng hoàn chỉnh: Bộ nén và giải nén tệp tin sử dụng thuật toán cây mã hóa Huffman.', 'Viết báo cáo khoa học ngắn phân tích tỷ lệ nén và thời gian xử lý của cây Huffman trên các định dạng tệp văn bản khác nhau.'])], 'requirements': ['Kiến thức toán học phổ thông vững vàng, đặc biệt là phần lượng giác, hàm số và tổ hợp xác suất.', 'Máy tính cá nhân có cài đặt trình biên dịch GCC/G++ và môi trường lập trình C++ (CLion hoặc VS Code).', 'Tinh thần kiên trì và niềm say mê với các bài toán logic có tính thử thách cao.']}, 'guidance-khmt-y2': {'lead': 'Hướng dẫn chi tiết từ A-Z lộ trình làm chủ lập trình hướng đối tượng, kiến trúc máy tính chuyên sâu và nguyên lý hệ điều hành cho sinh viên khoa học máy tính.', 'p1': 'Bước sang năm thứ hai, sinh viên khoa học máy tính cần chuyển dịch từ tư duy lập trình hàm cơ bản sang tư duy trừu tượng hóa mô hình hướng đối tượng và khám phá sâu cơ chế vận hành bên dưới tầng phần cứng. Sự kết hợp giữa khả năng thiết kế phần mềm sạch và hiểu biết cặn kẽ về nguyên lý phân chia thời gian CPU, quản lý bộ nhớ ảo của hệ điều hành sẽ tạo tiền đề vững chắc cho việc thiết kế các hệ thống tính toán hiệu năng cao.', 'p2': 'Hiểu rõ cách thức một chương trình C++ được biên dịch sang mã máy Assembly, cách các luồng (threads) tranh chấp tài nguyên và cách hệ điều hành điều phối tiến trình là ranh giới phân định giữa một thợ gõ mã thông thường và một nhà khoa học máy tính thực thụ.', 'roles': [('Lập trình viên C/C++ hệ thống (Systems Software Developer)', 'Tham gia phát triển các thư viện tính toán hiệu năng cao, module điều khiển thiết bị hoặc công cụ phân tích mã nguồn.'), ('Kỹ sư phần mềm nhúng tập sự (Junior Embedded Engineer)', 'Lập trình vi điều khiển, tối ưu hóa kích thước bộ nhớ và xử lý ngắt phần cứng theo thời gian thực.'), ('Trợ lý nghiên cứu kiến trúc máy tính', 'Thực hiện mô phỏng kiến trúc vi xử lý trên các công cụ mô phỏng học thuật (Gem5, Simplescalar).')], 'stages': [('Giai đoạn 1: Lập trình hướng đối tượng chuyên sâu với C++ & Mẫu thiết kế', ['Làm chủ 4 trụ cột OOP: Đóng gói (Encapsulation), Kế thừa (Inheritance), Đa hình (Polymorphism) và Trừu tượng (Abstraction).', 'Hiểu cơ chế bảng ảo (Vtable) và con trỏ vptr trong C++ để giải quyết đa hình động tại thời điểm chạy (Runtime).', 'Áp dụng nguyên lý quản lý tài nguyên tự động RAII (Resource Acquisition Is Initialization) và con trỏ thông minh (unique_ptr, shared_ptr).', 'Cài đặt các mẫu thiết kế kinh điển: Singleton, Factory, Observer và Strategy trong một dự án mô phỏng hệ thống ngân hàng.']), ('Giai đoạn 2: Kiến trúc tập lệnh CPU, Assembly x86/ARM & Quản lý bộ nhớ', ['Tìm hiểu kiến trúc tập lệnh ISA (Instruction Set Architecture), tập thanh ghi đa năng và cờ trạng thái của CPU x86-64.', 'Biên dịch mã nguồn C++ sang Assembly và phân tích cách tổ chức khung ngăn xếp hàm (Stack Frame, Base Pointer, Stack Pointer).', 'Nghiên cứu cơ chế Cache Hierarchy (L1, L2, L3 Cache) và tối ưu hóa tính cục bộ không gian/thời gian (Cache Locality) trong thuật toán nhân ma trận.', 'Sử dụng công cụ GDB để gỡ lỗi mã máy ở cấp thanh ghi và phân tích nguyên nhân lỗi tràn bộ đệm (Buffer Overflow).']), ('Giai đoạn 3: Nguyên lý hệ điều hành, lập trình đa luồng & Đồng bộ hóa Semaphore', ['Hiểu rõ trạng thái vòng đời của tiến trình (Process Lifecycle), cơ chế chuyển ngữ cảnh (Context Switching) và lời gọi hệ thống (System Calls).', 'Lập trình đa luồng chuẩn POSIX Threads (pthreads) trong C++: tạo luồng, truyền đối số và thu hồi luồng (thread join/detach).', 'Giải quyết triệt để vấn đề điều kiện chạy đua (Race Condition) và tắc nghẽn (Deadlock) bằng Mutex, Condition Variables và Semaphore.', 'Giải quyết bài toán kinh điển: Bữa ăn của các triết gia (Dining Philosophers) và bài toán Nhà sản xuất - Người tiêu dùng (Producer-Consumer).']), ('Giai đoạn 4: Bộ nhớ ảo, hệ thống tệp tin & Đồ án mô phỏng hệ điều hành thu nhỏ', ['Nghiên cứu cơ chế phân trang (Paging), bảng trang (Page Table), bộ đệm chuyển đổi địa chỉ (TLB) và các thuật toán thay trang (LRU, FIFO).', 'Phân tích cấu trúc hệ thống tệp tin (File System Inode), cấp phát khối dữ liệu và cơ chế ghi nhật ký (Journaling).', 'Xây dựng đồ án mô phỏng hệ điều hành thu nhỏ (Toy OS Simulator): bộ điều phối CPU đa mức phản hồi (MLFQ) và quản lý bộ nhớ ảo.', 'Viết báo cáo đánh giá hiệu năng thuật toán điều phối thông qua các chỉ số thời gian chờ trung bình (Average Waiting Time) và thông lượng (Throughput).'])], 'reqs': ['Đã thành thạo lập trình C/C++ căn bản và cấu trúc dữ liệu năm nhất.', 'Môi trường phát triển Linux (Ubuntu LTS) và bộ công cụ GNU Toolchain (gcc, g++, gdb, make).', 'Tư duy trừu tượng hóa hệ thống phần cứng và khả năng kiên trì đọc tài liệu kiến trúc máy tính chuyên ngành.']}, 'guidance-khmt-y3': {'lead': 'Hướng dẫn chi tiết từ A-Z lộ trình nghiên cứu thuật toán đồ thị nâng cao, giải thuật quy hoạch động và nhập môn học máy dành cho sinh viên khoa học máy tính.', 'p1': 'Năm thứ ba đánh dấu bước nhảy vọt từ các bài toán tính toán cơ bản sang các bài toán tối ưu tổ hợp phức tạp và mở rộng sang lĩnh vực trí tuệ nhân tạo. Đồ thị là mô hình toán học mạnh mẽ nhất để biểu diễn các mạng lưới trong thế giới thực: từ mạng xã hội, mạng lưới giao thông đến bản đồ tương tác protein. Nắm vững thuật toán đồ thị nâng cao giúp sinh viên giải quyết những bài toán quy mô lớn với độ phức tạp tối ưu.', 'p2': 'Bên cạnh đó, việc tiếp cận học máy (Machine Learning) từ góc nhìn toán học chặt chẽ (đại số tuyến tính, tối ưu hóa lồi, lý thuyết xác suất) sẽ giúp bạn hiểu rõ cơ chế học của mô hình thay vì chỉ sử dụng các thư viện như một hộp đen.', 'roles': [('Kỹ sư thuật toán tập sự (Algorithm Engineer Intern)', 'Phát triển và tối ưu hóa các giải thuật định tuyến, phân bổ tài nguyên và lập lịch tự động.'), ('Kỹ sư học máy tập sự (Junior ML Engineer)', 'Tiền xử lý tập dữ liệu lớn, trích xuất đặc trưng và huấn luyện các mô hình phân loại/dự báo cơ sở.'), ('Trợ lý nghiên cứu trí tuệ nhân tạo (AI Research Intern)', 'Tham gia đọc tài liệu học thuật tại các hội nghị NeurIPS/ICML và tái lập kết quả thực nghiệm.')], 'stages': [('Giai đoạn 1: Thuật toán đồ thị nâng cao & Cây khung nhỏ nhất', ['Làm chủ các thuật toán tìm đường đi ngắn nhất: Dijkstra với hàng đợi ưu tiên Heap O((V+E)logV), Bellman-Ford xử lý trọng số âm và Floyd-Warshall O(V^3).', 'Hiện thực hóa thuật toán tìm cây khung nhỏ nhất (Kruskal với cấu trúc Disjoint Set Union DSU, Prim) và ứng dụng trong thiết kế mạng viễn thông.', 'Nghiên cứu thuật toán tìm thành phần liên thông mạnh (Tarjan, Kosaraju) và thuật toán sắp xếp tô-pô (Topological Sort) cho đồ án luồng công việc.', 'Giải quyết bài toán luồng cực đại trong mạng (Max Flow - Min Cut) bằng thuật toán Ford-Fulkerson và Edmonds-Karp.']), ('Giai đoạn 2: Quy hoạch động nâng cao & Lý thuyết độ phức tạp tính toán (P vs NP)', ['Rèn luyện tư duy quy hoạch động (Dynamic Programming): xác định trạng thái, công thức truy hồi và tối ưu hóa không gian lưu trữ bộ nhớ.', 'Giải quyết các dạng bài toán quy hoạch động nâng cao: quy hoạch động trên cây (Tree DP), quy hoạch động bitmask và tối ưu hóa bao lồi (Convex Hull Trick).', 'Nghiên cứu lý thuyết độ phức tạp tính toán: phân loại lớp bài toán P, NP, NP-đầy đủ (NP-Complete) và phép quy dẫn thời gian đa thức.', 'Áp dụng các giải thuật xấp xỉ (Approximation Algorithms) và giải thuật heuristic để tìm nghiệm gần đúng cho bài toán Người du lịch (TSP).']), ('Giai đoạn 3: Nhập môn học máy (Machine Learning) & Tối ưu hóa Gradient Descent', ['Nắm vững cơ sở toán học của học máy: đạo hàm riêng, ma trận Jacobian, Hessian và hàm mất mát (Loss Function).', 'Tự cài đặt từ đầu bằng Python/NumPy thuật toán hồi quy tuyến tính (Linear Regression) và hồi quy logistic (Logistic Regression) với Gradient Descent.', 'Hiểu bản chất hiện tượng Overfitting/Underfitting, kỹ thuật điều hòa trọng số L1/L2 (Lasso/Ridge) và phương pháp đánh giá chéo (K-Fold Cross Validation).', 'Sử dụng thư viện Scikit-learn để xây dựng hệ thống phân loại chữ số viết tay trên bộ dữ liệu kinh điển MNIST với độ chính xác trên 98%.']), ('Giai đoạn 4: Thiết kế hệ thống tính toán phân tán & Đồ án thuật toán ứng dụng', ['Nghiên cứu mô hình tính toán song song đa lõi với OpenMP và mô hình tính toán phân tán MapReduce.', 'Xây dựng đồ án phân tích mạng xã hội thu nhỏ: tính toán chỉ số trung tâm (Betweenness Centrality, PageRank) trên đồ thị 100,000 đỉnh.', 'Đo lường thời gian thực thi thuật toán song song và tính toán hệ số tăng tốc (Speedup Factor) theo định luật Amdahl.', 'Trình bày kết quả nghiên cứu dưới dạng bài báo học thuật theo định dạng IEEE Transactions và phản biện trước nhóm chuyên môn.'])], 'reqs': ['Đã hoàn thành học phần Cấu trúc dữ liệu & Giải thuật và Đại số tuyến tính.', 'Thành thạo lập trình C++ và Python khoa học (NumPy, SciPy, Matplotlib).', 'Khả năng đọc hiểu tài liệu nghiên cứu khoa học tiếng Anh.']}, 'guidance-khmt-y4': {'lead': 'Hướng dẫn chi tiết từ A-Z lộ trình nghiên cứu ứng dụng khoa học dữ liệu, thuật toán tối ưu hóa và chuyển tiếp sự nghiệp học thuật hoặc doanh nghiệp R&D.', 'p1': 'Năm cuối cùng của chuyên ngành Khoa học máy tính là giai đoạn sinh viên nâng tầm tư duy nghiên cứu độc lập, hoàn thiện các công trình khoa học có giá trị thực tiễn và chuẩn bị hành trang bước ra các môi trường học thuật quốc tế hoặc các phòng nghiên cứu R&D của các tập đoàn công nghệ lớn. Trọng tâm của giai đoạn này là giải quyết các bài toán tối ưu hóa quy mô lớn và ứng dụng các mô hình học sâu hiện đại.', 'p2': 'Dù lựa chọn con đường làm tiến sĩ/thạc sĩ hay làm việc trong ngành công nghiệp, năng lực chứng minh tính đúng đắn của thuật toán, kỹ năng viết bài báo khoa học và sự trung thực học thuật luôn là những phẩm chất được đề cao nhất.', 'roles': [('Nghiên cứu viên khoa học máy tính (Computer Science Researcher)', 'Thực hiện các đề tài nghiên cứu chuyên sâu, phát triển mô hình tính toán mới và công bố bài báo khoa học.'), ('Kỹ sư nghiên cứu & phát triển (R&D Engineer)', 'Chuyển giao các kết quả nghiên cứu học thuật thành các module sản phẩm có tính ứng dụng thực tế.'), ('Chuyên viên tư vấn thuật toán & Dữ liệu lớn', 'Phân tích và tư vấn giải pháp tối ưu hóa tính toán cho các hệ thống tài chính, logistics phức tạp.')], 'stages': [('Giai đoạn 1: Phương pháp luận nghiên cứu & Xác định đề tài khóa luận tốt nghiệp', ['Tra cứu và tổng quan y văn (Literature Review) từ các cơ sở dữ liệu học thuật uy tín: ACM Digital Library, IEEE Xplore, arXiv.', 'Xác định khoảng trống nghiên cứu (Research Gap), phát biểu bài toán toán học chính xác và đặt ra các câu hỏi nghiên cứu cụ thể.', 'Thiết kế khung thực nghiệm (Experimental Framework): lựa chọn bộ dữ liệu chuẩn (Benchmark Datasets) và các chỉ số đo lường định lượng.', 'Lập đề cương nghiên cứu khóa luận tốt nghiệp chi tiết và bảo vệ thành công trước hội đồng chuyên môn khoa.']), ('Giai đoạn 2: Hiện thực hóa mô hình toán học & Tối ưu hóa thuật toán thực nghiệm', ['Cài đặt thuật toán đề xuất bằng C++/CUDA hoặc PyTorch với thiết kế module linh hoạt cho việc thử nghiệm các biến thể siêu tham số.', 'Tiến hành kiểm chứng thực nghiệm trên cụm máy tính hiệu năng cao (HPC/GPU Cloud), thu thập số liệu hội tụ và thời gian thực thi.', 'Thực hiện phân tích độ nhạy (Ablation Study) để chứng minh đóng góp của từng thành phần trong mô hình đề xuất.', 'So sánh định lượng kết quả với ít nhất 3 phương pháp đối sánh (Baseline Methods) tiên tiến nhất hiện nay (State-of-the-Art).']), ('Giai đoạn 3: Viết bài báo khoa học chuẩn quốc tế & Đóng gói mã nguồn Reproducible', ['Soạn thảo bài báo khoa học hoàn chỉnh bằng LaTeX theo định dạng chuẩn của IEEE hoặc ACM: Tóm tắt, Mở đầu, Phương pháp, Thực nghiệm, Kết luận.', 'Thiết kế các biểu đồ khoa học trực quan (Boxplot, ROC curve, Heatmap) với độ phân giải cao và diễn giải số liệu chặt chẽ.', 'Chuẩn hóa mã nguồn thực nghiệm lên GitHub kèm tệp hướng dẫn tái lập kết quả (Reproducibility Guide) và môi trường Docker.', 'Gửi bài báo khoa học tham dự hội nghị sinh viên nghiên cứu khoa học cấp trường hoặc hội thảo chuyên ngành quốc tế.']), ('Giai đoạn 4: Bảo vệ khóa luận xuất sắc & Định hướng chuyển tiếp sự nghiệp', ['Chuẩn bị bài thuyết trình bảo vệ khóa luận tốt nghiệp: rèn luyện kỹ năng trình bày logic trong 15 phút và trả lời phản biện học thuật.', 'Hoàn thiện hồ sơ xin học bổng Thạc sĩ/Tiến sĩ: viết bài luận mục đích (Statement of Purpose), thư giới thiệu và CV học thuật.', 'Luyện tập phỏng vấn các vị trí R&D/Algorithm Engineer: phân tích bài toán kiến trúc hệ thống và thuật toán nâng cao.', 'Tốt nghiệp với khóa luận loại xuất sắc và tự tin gia nhập các phòng nghiên cứu công nghệ hàng đầu.'])], 'reqs': ['Tích lũy đầy đủ tín chỉ học phần và có điểm trung bình học thuật (GPA) khá/giỏi trở lên.', 'Khả năng viết học thuật bằng tiếng Anh và sử dụng thành thạo hệ soạn thảo LaTeX.', 'Tác phong làm việc khoa học, trung thực và tôn trọng bản quyền sở hữu trí tuệ.']}, 'guidance-ktpm-y1': {'lead': 'Hướng dẫn chi tiết từ A-Z lộ trình tiếp cận tư duy kỹ thuật phần mềm, tiêu chuẩn viết mã sạch và phương pháp quản lý mã nguồn chuyên nghiệp dành cho sinh viên năm nhất.', 'p1': 'Kỹ thuật phần mềm (Software Engineering) không chỉ là lập trình để máy tính hiểu, mà là nghệ thuật và khoa học xây dựng các hệ thống phần mềm có khả năng mở rộng, bảo trì và thích ứng với sự thay đổi liên tục của yêu cầu nghiệp vụ. Trong môi trường công nghiệp, mã nguồn được đọc nhiều hơn gấp 10 lần so với thời gian viết. Do đó, rèn luyện thói quen viết mã sạch (Clean Code), hiểu rõ vòng đời phát triển phần mềm (SDLC) và thành thạo Git ngay từ năm nhất là chìa khóa để trở thành kỹ sư xuất sắc.', 'p2': 'Người mới bắt đầu thường có xu hướng viết mã vội vàng để chạy được kết quả mà bỏ qua tính rõ ràng, cấu trúc mô-đun và việc kiểm thử. Lộ trình dưới đây sẽ dẫn dắt bạn qua 4 chặng đường thực chiến giúp bạn xây dựng phong cách kỹ sư chuẩn mực ngay từ dòng lệnh đầu tiên.', 'roles': [('Lập trình viên tập sự (Junior Developer Trainee)', 'Viết mã các tính năng cơ bản, tuân thủ hướng dẫn phong cách lập trình và khắc phục lỗi nhỏ.'), ('Kiểm thử viên thủ công tập sự (Manual QA Trainee)', 'Thực thi các kịch bản kiểm thử theo tài liệu mô tả yêu cầu và ghi nhận lỗi vào hệ thống.'), ('Cộng tác viên hỗ trợ tài liệu phần mềm', 'Tham gia cập nhật tài liệu kỹ thuật, hướng dẫn sử dụng và kiểm tra tính nhất quán của tài liệu API.')], 'stages': [('Giai đoạn 1: Tiếp cận vòng đời phát triển phần mềm (SDLC) & Cú pháp TypeScript', ['Nắm vững các giai đoạn trong vòng đời phần mềm: Khảo sát yêu cầu, Thiết kế, Hiện thực, Kiểm thử, Triển khai và Bảo trì.', 'Hiểu rõ sự khác biệt giữa mô hình Thác nước (Waterfall) truyền thống và triết lý Phát triển linh hoạt (Agile Manifesto).', 'Làm quen với cú pháp ngôn ngữ TypeScript: hệ thống kiểu tĩnh (Static Typing), giao diện (Interface), kiểu kết hợp (Union Types) và Generics.', 'Thực hành viết chương trình quản lý thông tin sinh viên bằng TypeScript có kiểm tra nghiêm ngặt kiểu dữ liệu khi biên dịch.']), ('Giai đoạn 2: Tiêu chuẩn viết mã sạch (Clean Code) & Xử lý ngoại lệ chuẩn', ['Áp dụng nguyên tắc đặt tên: tên biến, hàm, lớp phải phản ánh đúng ý định (Intention-Revealing Names) và không dùng từ viết tắt tối nghĩa.', 'Tuân thủ quy tắc hàm đơn nhiệm: mỗi hàm chỉ thực hiện một việc duy nhất, số lượng tham số dưới 3 và không có tác dụng phụ (Side Effects).', 'Xây dựng cơ chế xử lý ngoại lệ bài bản: phân biệt rõ ràng giữa lỗi người dùng (Client Error) và lỗi hệ thống (System Exception).', 'Thực hành tái cấu trúc (Refactoring) một đoạn mã lộn xộn (Spaghetti Code) 200 dòng thành các mô-đun sạch sẽ, dễ đọc.']), ('Giai đoạn 3: Làm chủ Git chuyên sâu: Rebase, Cherry-pick & Quản lý nhánh Feature Branching', ['Hiểu rõ kiến trúc bên trong của Git: cấu trúc Directed Acyclic Graph (DAG), các đối tượng commit, tree, blob và con trỏ HEAD.', 'Thành thạo kỹ thuật Git nâng cao: phân biệt giữa Git Merge và Git Rebase, sử dụng git stash lưu tạm công việc và git cherry-pick chọn lọc commit.', 'Thực hành quy trình Feature Branching: tạo nhánh tính năng từ main, tạo Pull Request (PR), yêu cầu duyệt mã và giải quyết xung đột (Merge Conflict).', 'Áp dụng tiêu chuẩn viết thông điệp commit theo Conventional Commits (feat, fix, refactor, docs) và gắn mã thẻ công việc (Jira Ticket ID).']), ('Giai đoạn 4: Đồ án nhóm đầu tay, thực hành Code Review & Đóng gói sản phẩm', ['Phối hợp nhóm 3-4 thành viên phát triển ứng dụng quản lý công việc (Todo List nâng cao) có lưu trữ dữ liệu cục bộ.', 'Thực hiện văn hóa Code Review: đọc mã nguồn của bạn cùng nhóm, đưa ra nhận xét mang tính xây dựng trên GitHub PR trước khi hòa trộn mã.', 'Cấu hình công cụ kiểm tra chất lượng mã tự động: ESLint để bắt lỗi cú pháp và Prettier để chuẩn hóa định dạng mã nguồn.', 'Hoàn thiện tệp README.md chuyên nghiệp với hướng dẫn cài đặt, quy ước đóng góp mã nguồn (Contributing Guidelines) và giấy phép bản quyền.'])], 'reqs': ['Máy tính cá nhân có cài đặt Node.js LTS, Git và trình biên tập VS Code.', 'Tư duy làm việc nhóm cởi mở và tinh thần tiếp thu các phản hồi đóng góp mã nguồn.', 'Thời gian thực hành tối thiểu 8 giờ mỗi tuần để viết mã và tham gia thảo luận nhóm.']}, 'guidance-ktpm-y2': {'lead': 'Hướng dẫn chi tiết từ A-Z lộ trình phát triển ứng dụng Web Fullstack hiện đại với React ở phía giao diện và Node.js ở phía máy chủ dành cho sinh viên kỹ thuật phần mềm.', 'p1': 'Phát triển Web Fullstack là kỹ năng cốt lõi giúp kỹ sư phần mềm có khả năng xây dựng độc lập các sản phẩm số hoàn chỉnh từ giao diện người dùng đến tầng dịch vụ dữ liệu phía sau. Sự kết hợp giữa React - thư viện giao diện theo mô hình thành phần phổ biến nhất thế giới và Node.js - môi trường thực thi JavaScript phi chặn ở máy chủ mang lại sự nhất quán vượt trội trong toàn bộ ngăn xếp công nghệ.', 'p2': 'Để xây dựng các ứng dụng web chất lượng thương mại, sinh viên không chỉ dừng lại ở việc ghép nối các thư viện mà cần hiểu sâu về cơ chế đồng bộ hóa trạng thái giao diện, kiến trúc luồng dữ liệu một chiều và nguyên lý thiết kế API không trạng thái (Stateless API).', 'roles': [('Lập trình viên Frontend React (Junior React Developer)', 'Phát triển giao diện web tương tác, tối ưu hóa trải nghiệm người dùng và tích hợp API máy chủ.'), ('Lập trình viên Backend Node.js (Junior Node.js Developer)', 'Xây dựng các dịch vụ RESTful API, thiết kế cơ sở dữ liệu quan hệ và bảo mật điểm cuối.'), ('Kỹ sư phần mềm Fullstack tập sự (Fullstack Intern)', 'Tham gia phát triển cả hai tầng ứng dụng trong các nhóm phát triển tính năng (Feature Teams).')], 'stages': [('Giai đoạn 1: Nền tảng TypeScript chuyên sâu & Lập trình bất đồng bộ hiện đại', ['Nắm vững JavaScript ES6+: Destructuring, Spread operator, Arrow functions, Array methods (map, filter, reduce).', 'Làm chủ mô hình bất đồng bộ: Phân biệt Callbacks, Promises và cú pháp Async/Await, xử lý lỗi với try/catch lồng nhau.', 'Ứng dụng TypeScript nâng cao trong dự án: Generics, Utility Types (Partial, Pick, Omit) và kiểm soát Type Narrowing.', 'Xây dựng thư viện tiện ích nhỏ xử lý chuyển đổi dữ liệu và định dạng ngày tháng có kiểm thử đơn vị với Vitest.']), ('Giai đoạn 2: Lập trình giao diện thành phần với React, Hooks & Tailwind CSS', ['Hiểu rõ cơ chế Virtual DOM, chu trình render và quy tắc hoạt động của React Hooks (useState, useEffect, useMemo, useCallback).', 'Thiết kế hệ thống thành phần giao diện (Component Hierarchy) tái sử dụng cao tuân thủ nguyên lý Atomic Design.', 'Xây dựng giao diện hiện đại, chuẩn Responsive trên mọi kích thước màn hình với Tailwind CSS phiên bản mới nhất.', 'Quản lý trạng thái ứng dụng: phân biệt trạng thái cục bộ (Component State), trạng thái toàn cục (Context API/Zustand) và Server Cache (TanStack Query).']), ('Giai đoạn 3: Xây dựng RESTful API với Node.js, Express & Prisma ORM', ['Xây dựng máy chủ Express.js chuẩn kiến trúc: Router -> Controller -> Service -> Data Access Layer.', 'Sử dụng Prisma ORM để quản lý schema cơ sở dữ liệu PostgreSQL: tạo migration tự động, định nghĩa quan hệ và truy vấn type-safe.', 'Triển khai xác thực người dùng an toàn: cơ chế Access Token (JWT ngắn hạn) và Refresh Token (lưu bảo mật trong HttpOnly Cookie).', 'Xây dựng middleware kiểm tra dữ liệu đầu vào (Input Validation) bằng Zod để loại bỏ các dữ liệu rác trước khi chạm vào cơ sở dữ liệu.']), ('Giai đoạn 4: Tích hợp hệ thống Fullstack hoàn chỉnh & Đóng gói Docker Compose', ['Kết nối toàn diện giữa React Frontend và Express Backend: xử lý đồng bộ hóa dữ liệu, thông báo trạng thái tải (Loading/Skeleton) và xử lý lỗi mạng.', 'Đóng gói ứng dụng Fullstack vào Docker Compose gồm: NGINX Reverse Proxy, React SPA build tĩnh, Express API và cơ sở dữ liệu PostgreSQL.', 'Tối ưu hóa hiệu năng web: nén tài nguyên, chia nhỏ gói tải (Code Splitting với React.lazy) và kiểm tra điểm số Google Lighthouse trên 90.', 'Triển khai ứng dụng thực tế lên môi trường đám mây miễn phí (Vercel cho Frontend, Render cho Backend) có tên miền tùy chỉnh.'])], 'reqs': ['Đã hoàn thành các học phần lập trình cơ sở và kiến thức mạng máy tính căn bản.', 'Cài đặt môi trường Node.js 20+, Docker Desktop và hệ quản trị PostgreSQL trên máy cá nhân.', 'Thói quen viết mã cẩn thận, chú trọng trải nghiệm người dùng và tính nhất quán giao diện.']}, 'guidance-ktpm-y3': {'lead': 'Hướng dẫn chi tiết từ A-Z lộ trình làm chủ đảm bảo chất lượng phần mềm, tự động hóa kiểm thử và vận hành quy trình phát triển linh hoạt Agile/Scrum.', 'p1': 'Một sản phẩm phần mềm thành công không chỉ được đo bằng số lượng tính năng mà trước hết bằng độ tin cậy, tính ổn định và khả năng hoạt động không lỗi trong mọi tình huống thực tế. Trong kỹ thuật phần mềm hiện đại, kiểm thử không phải là công đoạn cuối cùng trước khi bàn giao mà được tích hợp liên tục trong mọi bước của chu trình phát triển thông qua tự động hóa kiểm thử và văn hóa chất lượng toàn diện.', 'p2': 'Sinh viên năm ba cần chuyển dịch từ việc kiểm thử thủ công bấm nút trên màn hình sang tư duy tự động hóa: viết các đoạn mã kiểm tra tính đúng đắn của chính mã nguồn khác, xây dựng kim tự tháp kiểm thử (Testing Pyramid) và điều phối công việc theo các sprint của phương pháp Scrum.', 'roles': [('Kỹ sư kiểm thử tự động (Automation QA Engineer)', 'Xây dựng các bộ kiểm thử tự động cho API và giao diện, tích hợp vào đường ống CI/CD.'), ('Kỹ sư đảm bảo chất lượng phần mềm (QA Specialist)', 'Lập kế hoạch kiểm thử, thiết kế ma trận kiểm thử và theo dõi chỉ số lỗi phần mềm.'), ('Scrum Master tập sự / Trợ lý quản lý dự án Agile', 'Điều phối các cuộc họp sprint, hỗ trợ gỡ bỏ rào cản công việc và theo dõi biểu đồ Burndown Chart.')], 'stages': [('Giai đoạn 1: Nền tảng kiểm thử phần mềm, kỹ thuật thiết kế Test Case & QA/QC', ['Phân biệt rõ ràng giữa Kiểm soát chất lượng (QC) và Đảm bảo chất lượng (QA), các cấp độ kiểm thử trong mô hình chữ V.', 'Áp dụng các kỹ thuật thiết kế Test Case hộp đen: Phân vùng tương đương (Equivalence Partitioning) và Phân tích giá trị biên (Boundary Value Analysis).', 'Thiết kế Test Case hộp trắng: Độ bao phủ câu lệnh (Statement Coverage), độ bao phủ nhánh (Branch Coverage) và độ bao phủ đường đi (Path Coverage).', 'Lập bảng kế hoạch kiểm thử (Test Plan) chi tiết cho một phân hệ xác thực và thanh toán trực tuyến.']), ('Giai đoạn 2: Tự động hóa kiểm thử đơn vị & Kiểm thử tích hợp với Vitest/Jest', ['Hiểu rõ triết lý Phát triển hướng kiểm thử TDD (Test-Driven Development): Red -> Green -> Refactor.', 'Viết các bài kiểm thử đơn vị (Unit Tests) toàn diện: kiểm tra các hàm nghiệp vụ, xử lý ngoại lệ và các giá trị biên null/undefined.', 'Làm chủ kỹ thuật Mocking và Stubbing: giả lập các hàm gọi cơ sở dữ liệu, dịch vụ bên thứ ba và đồng hồ thời gian hệ thống.', 'Đạt chỉ số bao phủ mã nguồn (Code Coverage) trên 80% với báo cáo chi tiết theo định dạng lcov/html.']), ('Giai đoạn 3: Kiểm thử tự động End-to-End với Playwright & Kiểm thử hiệu năng k6', ['Cài đặt và thiết lập bộ khung kiểm thử giao diện End-to-End (E2E) tự động bằng Playwright trên nhiều trình duyệt (Chromium, Firefox, WebKit).', 'Áp dụng mẫu thiết kế Page Object Model (POM) để tái sử dụng mã kiểm thử giao diện và giảm chi phí bảo trì kịch bản.', 'Viết kịch bản kiểm thử tải máy chủ API bằng công cụ k6: đo lường thông số thời gian phản hồi ở mức tải 500 yêu cầu/giây.', 'Tích hợp các kịch bản kiểm thử tự động vào luồng GitHub Actions để tự động từ chối hòa trộn mã khi có bài test thất bại.']), ('Giai đoạn 4: Vận hành quy trình Agile/Scrum trên Jira & Báo cáo chất lượng dự án', ['Làm quen với các nghi thức Scrum: Sprint Planning, Daily Standup, Sprint Review và Sprint Retrospective.', 'Quản lý danh mục công việc (Product Backlog), ước lượng độ phức tạp công việc bằng Story Points và kỹ thuật Planning Poker.', 'Theo dõi tiến độ phát triển thông qua bảng Agile Board trên Jira và phân tích biểu đồ tiến độ dự án (Burndown Chart).', 'Tổng hợp báo cáo chất lượng phần mềm (Test Summary Report) đánh giá tỷ lệ phát hiện lỗi, mật độ lỗi và khuyến nghị sẵn sàng phát hành.'])], 'reqs': ['Đã có kinh nghiệm phát triển ứng dụng Web Frontend và Backend cơ bản.', 'Tư duy tỉ mỉ, khả năng tìm kiếm các trường hợp biên và tư duy phản biện sản phẩm.', 'Hiểu biết căn bản về chu trình phát triển phần mềm và công cụ quản lý tác vụ Jira/Trello.']}, 'guidance-ktpm-y4': {'lead': 'Hướng dẫn chi tiết từ A-Z lộ trình thiết kế kiến trúc phần mềm nâng cao, hoàn thiện đồ án doanh nghiệp thực tế và chinh phục nhà tuyển dụng vị trí kỹ sư phần mềm.', 'p1': 'Năm thứ tư là bước đệm then chốt chuyển hóa toàn bộ kiến thức học thuật thành năng lực kỹ thuật công nghiệp chuẩn mực. Một kỹ sư phần mềm chuẩn bị tốt nghiệp cần sở hữu tư duy kiến trúc hệ thống trưởng thành: biết cách cân nhắc sự đánh đổi (Trade-offs) giữa tính sẵn sàng, tính nhất quán và hiệu năng, áp dụng chuẩn xác các mẫu kiến trúc vi dịch vụ hoặc module độc lập và khả năng bảo vệ giải pháp kỹ thuật trước các chuyên gia.', 'p2': 'Thị trường công nghệ cao yêu cầu ứng viên không chỉ dừng lại ở các bài toán mẫu mà phải chứng minh được kinh nghiệm giải quyết các vấn đề phức tạp trong dự án thực tế. Lộ trình dưới đây sẽ đồng hành cùng bạn từ khâu thiết kế kiến trúc phân tầng đến lúc tự tin vượt qua các vòng phỏng vấn chuyên sâu.', 'roles': [('Kỹ sư phần mềm chính thức (Junior Software Engineer)', 'Thiết kế và phát triển các tính năng phức tạp, tối ưu hóa hiệu năng hệ thống và bảo trì dịch vụ production.'), ('Kỹ sư kiến trúc giải pháp tập sự (Associate Solutions Architect)', 'Hỗ trợ đánh giá kiến trúc phần mềm, lựa chọn công nghệ và thiết kế mô hình tích hợp hệ thống.'), ('Kỹ sư đảm bảo độ tin cậy dịch vụ (SRE / Platform Engineer)', 'Giám sát độ sẵn sàng hệ thống, xử lý sự cố môi trường production và tự động hóa hạ tầng.')], 'stages': [('Giai đoạn 1: Mẫu kiến trúc phần mềm nâng cao & Thiết kế theo miền (DDD)', ['Nghiên cứu sâu các mẫu kiến trúc phần mềm kinh điển: Kiến trúc phân tầng (Layered), Kiến trúc hình lục giác (Hexagonal / Ports and Adapters) và Clean Architecture.', 'Tiếp cận phương pháp Thiết kế hướng miền (Domain-Driven Design - DDD): Khái niệm Bounded Context, Entities, Value Objects, Aggregates và Domain Events.', 'Áp dụng nguyên lý phân tách trách nhiệm truy vấn và lệnh (CQRS) và Event Sourcing trong các bài toán giao dịch tài chính phức tạp.', 'Vẽ sơ đồ kiến trúc phần mềm theo mô hình C4 Model (Context, Container, Component, Code) cho đề tài đồ án tốt nghiệp.']), ('Giai đoạn 2: Hiện thực hóa đồ án doanh nghiệp thực tế & Xử lý bất đồng bộ', ['Phát triển đồ án quy mô lớn ứng dụng kiến trúc Microservices hoặc Modular Monolith theo tiêu chuẩn công nghiệp.', 'Tích hợp hàng đợi thông điệp Apache Kafka hoặc RabbitMQ để xử lý luồng dữ liệu bất đồng bộ và chống nghẽn dịch vụ.', 'Xây dựng cơ chế xử lý lỗi phân tán: mẫu thiết kế Circuit Breaker (với Opossum/Resilience4j), Retry có Exponential Backoff và Dead Letter Queue.', 'Thực hiện đo đạc và loại bỏ các điểm nghẽn hiệu năng (Profiling) trên cơ sở dữ liệu và mã nguồn ứng dụng.']), ('Giai đoạn 3: Triển khai hạ tầng đám mây, Container hóa & Giám sát quan sát (Observability)', ['Thiết lập cụm Kubernetes (K8s) cục bộ với Minikube hoặc K3s: triển khai Pods, Services, Ingress và ConfigMaps/Secrets.', 'Xây dựng đường ống CI/CD hoàn chỉnh trên GitHub Actions tự động kiểm thử, quét mã bảo mật (SonarQube) và triển khai tự động.', 'Tích hợp hệ sinh thái giám sát Observability: Logging tập trung (ELK Stack), Metrics (Prometheus/Grafana) và Phân tán dấu vết (Distributed Tracing với OpenTelemetry).', 'Tiến hành kiểm thử sự cố hỗn loạn (Chaos Engineering cơ bản): giả lập sự cố sập một vi dịch vụ và kiểm tra khả năng tự phục hồi của hệ thống.']), ('Giai đoạn 4: Hoàn thiện hồ sơ kỹ thuật, luyện phỏng vấn System Design & Nhận việc', ['Xây dựng trang Portfolio kỹ thuật trực tuyến và làm nổi bật các quyết định kiến trúc (Architectural Decision Records - ADR) trong dự án.', 'Luyện tập kỹ năng phỏng vấn thiết kế hệ thống (System Design Interview): phân tích quy mô, thiết kế API, mô hình dữ liệu và chiến lược mở rộng.', 'Chuẩn bị kỹ năng trả lời phỏng vấn văn hóa doanh nghiệp và giải quyết xung đột ý kiến kỹ thuật trong nhóm.', 'Ứng tuyển chính thức vào các công ty sản phẩm phần mềm (Product) và tập đoàn công nghệ đa quốc gia.'])], 'reqs': ['Đã hoàn thành xuất sắc đồ án chuyên ngành và hoàn tất kỳ thực tập kỹ sư phần mềm.', 'Năng lực tự chủ cao trong việc nghiên cứu tài liệu kỹ thuật nâng cao bằng tiếng Anh.', 'Tác phong làm việc chuyên nghiệp, tư duy phản biện kỹ thuật và khả năng giải trình quyết định thiết kế.']}, 'guidance-httt-y1': {'lead': 'Hướng dẫn chi tiết từ A-Z lộ trình phân tích quy trình nghiệp vụ, rèn luyện tư duy hệ thống và thiết kế cơ sở dữ liệu quan hệ dành cho sinh viên hệ thống thông tin.', 'p1': 'Hệ thống thông tin (Information Systems) là chiếc cầu nối chiến lược giữa công nghệ và thế giới kinh doanh. Khác với lập trình thuần túy, ngành Hệ thống thông tin tập trung vào việc hiểu sâu sắc cách một tổ chức vận hành, cách các dòng thông tin luân chuyển giữa các phòng ban và cách ứng dụng công nghệ để tối ưu hóa quy trình nghiệp vụ, giảm thiểu lãng phí và nâng cao hiệu quả hoạt động.', 'p2': 'Sinh viên năm nhất cần xây dựng tư duy hệ thống (Systems Thinking) – năng lực nhìn nhận một tổ chức như một tổng thể thống nhất gồm các thành phần tương tác lẫn nhau. Lộ trình dưới đây sẽ trang bị cho bạn phương pháp luận phân tích quy trình và làm chủ kỹ thuật cơ sở dữ liệu nền tảng.', 'roles': [('Thực tập sinh phân tích nghiệp vụ cơ sở', 'Hỗ trợ ghi nhận yêu cầu người dùng, khảo sát quy trình hiện tại và lập biên bản làm việc.'), ('Cộng tác viên quản trị dữ liệu (Data Administrator Intern)', 'Thực hiện nhập liệu, kiểm tra tính toàn vẹn của dữ liệu và viết truy vấn báo cáo đơn giản.'), ('Trợ lý dự án hệ thống thông tin', 'Hỗ trợ theo dõi tiến độ dự án, chuẩn bị tài liệu họp và phân loại tài liệu nghiệp vụ.')], 'stages': [('Giai đoạn 1: Nền tảng tư duy hệ thống & Khảo sát bài toán nghiệp vụ doanh nghiệp', ['Nắm vững các khái niệm cốt lõi: Dữ liệu (Data), Thông tin (Information), Tri thức (Knowledge) và giá trị của thông tin trong quản trị.', 'Phân tích cấu trúc tổ chức doanh nghiệp điển hình: khối mua hàng, kho vận, bán hàng, kế toán và nhân sự.', 'Rèn luyện kỹ năng khảo sát hiện trạng: kỹ thuật phỏng vấn cán bộ nghiệp vụ, thiết kế bảng câu hỏi khảo sát và quan sát thực địa.', 'Thực hiện bài tập phân tích quy trình bán hàng của một cửa hàng bán lẻ và chỉ ra các điểm nghẽn thông tin gây thất thoát.']), ('Giai đoạn 2: Mô hình hóa dòng dữ liệu DFD & Sơ đồ hóa quy trình nghiệp vụ', ['Học cách vẽ sơ đồ luồng dữ liệu DFD (Data Flow Diagram) từ mức ngữ cảnh (Context Diagram) đến các mức phân rã chi tiết.', 'Làm quen với chuẩn ký hiệu mô hình hóa quy trình nghiệp vụ BPMN 2.0: sự kiện, hoạt động, cổng rẽ nhánh và luồng thông điệp.', 'Sử dụng công cụ phần mềm chuyên dụng (draw.io, Microsoft Visio hoặc Lucidchart) để số hóa các sơ đồ quy trình.', 'Hoàn thành hồ sơ mô tả quy trình tiếp nhận và xử lý đơn hàng trực tuyến kèm ma trận trách nhiệm RACI.']), ('Giai đoạn 3: Thiết kế cơ sở dữ liệu quan hệ & Viết câu lệnh truy vấn SQL', ['Chuyển hóa sơ đồ quy trình nghiệp vụ thành mô hình dữ liệu thực thể quan hệ (ERD) hoàn chỉnh.', 'Áp dụng chuẩn hóa cơ sở dữ liệu (1NF, 2NF, 3NF) để đảm bảo tính nhất quán và loại bỏ trùng lặp dữ liệu nghiệp vụ.', 'Thành thạo ngôn ngữ truy vấn SQL: tạo bảng, ràng buộc khóa ngoại, truy vấn thống kê dữ liệu báo cáo với JOIN và GROUP BY.', 'Xây dựng cơ sở dữ liệu quản lý chuỗi cung ứng mini trên PostgreSQL và viết 20 câu truy vấn phục vụ báo cáo doanh thu theo tháng.']), ('Giai đoạn 4: Đồ án phân tích hệ thống thông tin đầu tay & Kỹ năng thuyết trình', ['Tổng hợp toàn bộ tài liệu khảo sát, sơ đồ quy trình DFD/BPMN và mô hình cơ sở dữ liệu thành báo cáo phân tích hệ thống hoàn chỉnh.', 'Đề xuất phương án cải tiến quy trình nghiệp vụ (To-Be Process) nhằm rút ngắn thời gian xử lý thủ tục hành chính.', 'Thiết kế slide thuyết trình trực quan, sử dụng số liệu định lượng để chứng minh tính khả thi của giải pháp đề xuất.', 'Bảo vệ đồ án phân tích hệ thống trước giảng viên và tiếp thu phản hồi phản biện để hoàn thiện kỹ năng giao tiếp chuyên môn.'])], 'reqs': ['Tư duy logic mạch lạc và khả năng giao tiếp, lắng nghe người khác.', 'Máy tính cá nhân cài đặt công cụ vẽ sơ đồ và hệ quản trị cơ sở dữ liệu (PostgreSQL/DBeaver).', 'Sự chủ động tìm hiểu các mô hình kinh doanh thực tế trong xã hội.']}, 'guidance-httt-y2': {'lead': 'Hướng dẫn chi tiết từ A-Z lộ trình làm chủ kỹ thuật phân tích nghiệp vụ (Business Analysis), thu thập yêu cầu và mô hình hóa hệ thống với UML dành cho sinh viên hệ thống thông tin.', 'p1': 'Trong kỷ nguyên chuyển đổi số, vai trò của Chuyên viên phân tích nghiệp vụ (Business Analyst - BA) trở nên quan trọng hơn bao giờ hết. BA là người thấu hiểu nỗi đau của người dùng doanh nghiệp, chuyển hóa những mong muốn mơ hồ thành tài liệu đặc tả kỹ thuật chính xác mà đội ngũ lập trình viên có thể hiện thực hóa mà không xảy ra hiểu lầm. Kỹ năng mô hình hóa UML là ngôn ngữ chuẩn quốc tế giúp bạn kết nối hai thế giới kinh doanh và công nghệ.', 'p2': 'Lộ trình năm thứ hai tập trung rèn luyện phương pháp luận BA theo chuẩn BABOK (Business Analysis Body of Knowledge): từ kỹ thuật gợi mở yêu cầu (Elicitation) đến lập hồ sơ đặc tả yêu cầu phần mềm (SRS) và thiết kế giao diện phác thảo (Wireframe).', 'roles': [('Chuyên viên phân tích nghiệp vụ tập sự (Junior Business Analyst)', 'Tham gia thu thập yêu cầu từ người dùng, viết tài liệu User Story và mô hình hóa Use Case.'), ('Chuyên viên kiểm thử chấp nhận người dùng (UAT Specialist)', 'Thiết kế kịch bản kiểm thử UAT và hướng dẫn người dùng cuối nghiệm thu hệ thống.'), ('Tư vấn viên giải pháp công nghệ (Solution Consultant Trainee)', 'Trình bày giải pháp phần mềm cho khách hàng và phân tích độ phù hợp của tính năng.')], 'stages': [('Giai đoạn 1: Kỹ thuật gợi mở & Phân loại yêu cầu nghiệp vụ theo chuẩn BABOK', ['Nắm vững 6 vùng tri thức của chuẩn BABOK và vai trò của BA trong từng giai đoạn dự án.', 'Áp dụng các kỹ thuật gợi mở yêu cầu thực chiến: phỏng vấn có cấu trúc, hội thảo nhóm (JAD Sessions), khảo sát và phân tích tài liệu cũ.', 'Phân biệt rõ ràng 4 cấp độ yêu cầu: Yêu cầu kinh doanh (Business Requirements), Yêu cầu các bên liên quan (Stakeholder Requirements), Yêu cầu giải pháp (Solution Requirements) và Yêu cầu chuyển giao (Transition Requirements).', 'Phân loại chi tiết yêu cầu chức năng (Functional Requirements) và phi chức năng (Non-Functional Requirements: bảo mật, hiệu năng, khả năng mở rộng).']), ('Giai đoạn 2: Mô hình hóa hệ thống với ngôn ngữ UML toàn diện', ['Thành thạo sơ đồ Use Case: xác định đúng Actor, ranh giới hệ thống, quan hệ include, extend và tổng quát hóa.', 'Viết tài liệu đặc tả ca sử dụng (Use Case Specification) chi tiết: luồng sự kiện chính (Basic Flow), luồng thay thế và luồng ngoại lệ.', 'Mô hình hóa hành vi hệ thống với Sơ đồ hoạt động (Activity Diagram) có các luồng bơi (Swimlanes) phân chia trách nhiệm.', 'Thiết kế Sơ đồ tuần tự (Sequence Diagram) mô tả sự tương tác thông điệp giữa các đối tượng theo trục thời gian.']), ('Giai đoạn 3: Viết tài liệu SRS, User Story & Thiết kế phác thảo Wireframe', ['Soạn thảo bộ tài liệu Đặc tả yêu cầu phần mềm hoàn chỉnh theo cấu trúc chuẩn IEEE 830 (Software Requirements Specification - SRS).', 'Áp dụng kỹ thuật viết User Story theo tiêu chí INVEST và thiết lập tiêu chí chấp nhận nghiệm thu (Acceptance Criteria) theo cú pháp Gherkin (Given-When-Then).', 'Sử dụng công cụ Figma hoặc Balsamiq để thiết kế khung nhìn màn hình phác thảo (Low-fidelity Wireframe) cho các tính năng cốt lõi.', 'Xây dựng ma trận truy xuất nguồn gốc yêu cầu (Requirements Traceability Matrix - RTM) để đảm bảo không sót yêu cầu trong khâu phát triển.']), ('Giai đoạn 4: Quản lý sự thay đổi yêu cầu, nghiệm thu UAT & Hồ sơ Portfolio BA', ['Hiểu quy trình quản lý thay đổi yêu cầu (Change Request Process): đánh giá tác động chi phí, tiến độ và rủi ro trước khi phê duyệt.', 'Lập kế hoạch và thiết kế kịch bản kiểm thử chấp nhận của người dùng cuối (User Acceptance Testing - UAT).', 'Đóng gói bộ hồ sơ năng lực BA (BA Portfolio) gồm tài liệu SRS mẫu, bộ sơ đồ UML hoàn chỉnh và video thuyết minh giải pháp.', 'Rèn luyện kỹ năng phỏng vấn tình huống nghiệp vụ (Case Interview) và chuẩn bị cho kỳ thi lấy chứng chỉ ECBA của IIBA.'])], 'reqs': ['Đã có kiến thức nền tảng về hệ thống thông tin và cơ sở dữ liệu quan hệ.', 'Kỹ năng viết văn bản tiếng Việt và tiếng Anh mạch lạc, chặt chẽ và không mơ hồ.', 'Khả năng tư duy phản biện và đồng cảm với nhu cầu của người sử dụng.']}, 'guidance-httt-y3': {'lead': 'Hướng dẫn chi tiết từ A-Z lộ trình triển khai giải pháp hoạch định nguồn lực doanh nghiệp (ERP), tích hợp hệ thống thông tin và quản trị dữ liệu quy mô lớn.', 'p1': 'Hệ thống hoạch định nguồn lực doanh nghiệp (Enterprise Resource Planning - ERP) là trái tim vận hành của các tập đoàn kinh tế và doanh nghiệp quy mô vừa và lớn. ERP tích hợp toàn diện mọi quy trình nghiệp vụ từ tài chính, chuỗi cung ứng, sản xuất đến nguồn nhân lực vào một nền tảng dữ liệu duy nhất. Sinh viên nắm vững kiến thức triển khai ERP và tích hợp hệ thống là nguồn nhân lực có giá trị cao hàng đầu trong thị trường công nghệ.', 'p2': 'Triển khai ERP không chỉ là cài đặt phần mềm mà là một cuộc chuyển đổi toàn diện về văn hóa doanh nghiệp và quy trình làm việc. Lộ trình dưới đây sẽ trang bị cho bạn kiến thức từ việc cấu hình giải pháp ERP mã nguồn mở đến các phương thức tích hợp dữ liệu hiện đại qua REST API và Webhooks.', 'roles': [('Chuyên viên tư vấn triển khai ERP tập sự (Junior ERP Consultant)', 'Tham gia cấu hình hệ thống, ánh xạ quy trình nghiệp vụ và đào tạo người dùng cuối.'), ('Kỹ sư tích hợp dữ liệu hệ thống (Systems Integration Engineer)', 'Xây dựng các cầu nối API truyền dữ liệu tự động giữa ERP và các hệ thống phụ trợ.'), ('Chuyên viên quản trị dữ liệu doanh nghiệp (Master Data Specialist)', 'Chuẩn hóa, làm sạch và giám sát tính toàn vẹn của danh mục dữ liệu chính của tổ chức.')], 'stages': [('Giai đoạn 1: Kiến trúc tổng thể hệ thống ERP & Các phân hệ cốt lõi', ['Nắm vững lịch sử phát triển từ MRP đến ERP hiện đại và kiến trúc 3 tầng điển hình của một giải pháp ERP quy mô lớn.', 'Nghiên cứu các phân hệ nghiệp vụ chính: Quản lý mua hàng (Procurement), Bán hàng (Sales Order), Kho vận (Inventory) và Kế toán tài chính (General Ledger).', 'Hiểu rõ mối liên kết dữ liệu giữa các phân hệ: từ đơn đặt hàng, phiếu xuất kho đến ghi nhận công nợ và hạch toán tự động.', 'Phân tích sự khác biệt giữa các giải pháp ERP hàng đầu thế giới (SAP S/4HANA, Oracle ERP) và các giải pháp mã nguồn mở (Odoo, ERPNext).']), ('Giai đoạn 2: Cài đặt, cấu hình & Vận hành giải pháp ERP mã nguồn mở (Odoo)', ['Triển khai môi trường Odoo Community trên máy chủ Linux với cơ sở dữ liệu PostgreSQL bằng Docker.', 'Thực hành cấu hình các thông số ban đầu của doanh nghiệp: cơ cấu công ty, tiền tệ, biểu đồ tài khoản kế toán và chính sách thuế.', 'Thiết lập quy trình Mua hàng - Nhập kho - Thanh toán (Procure-to-Pay) và quy trình Bán hàng - Xuất kho - Thu tiền (Order-to-Cash) trên Odoo.', 'Tùy biến giao diện và thêm các trường thông tin nghiệp vụ mới bằng công cụ Odoo Studio hoặc viết module Python mở rộng.']), ('Giai đoạn 3: Chuẩn hóa dữ liệu chính (Master Data) & Tích hợp hệ thống qua API', ['Hiểu tầm quan trọng của Quản trị dữ liệu chính (Master Data Management - MDM): danh mục khách hàng, nhà cung cấp, vật tư và giá.', 'Thực hành quy trình trích xuất, làm sạch và nạp dữ liệu (ETL) từ tệp Excel vào cơ sở dữ liệu ERP có kiểm tra tính hợp lệ.', 'Xây dựng dịch vụ tích hợp API kết nối giữa Odoo và website thương mại điện tử: tự động đồng bộ hóa đơn hàng và tồn kho qua RESTful API.', 'Xử lý lỗi truyền tin dữ liệu và đảm bảo tính nhất quán (Eventual Consistency) bằng cơ chế ghi nhật ký giao dịch tích hợp.']), ('Giai đoạn 4: Quản lý dự án triển khai ERP, quản trị sự thay đổi & Đồ án thực tế', ['Nghiên cứu phương pháp luận triển khai dự án ERP chuyên nghiệp (như SAP Activate hoặc Odoo Implementation Methodology).', 'Phân tích các rủi ro thất bại phổ biến trong dự án ERP và đề xuất kế hoạch Quản trị sự thay đổi (Change Management) cho người dùng.', 'Thực hiện đồ án mô phỏng triển khai hoàn chỉnh một phân hệ ERP cho một công ty sản xuất nhỏ gồm cấu hình và tài liệu hướng dẫn bàn giao.', 'Bảo vệ đồ án triển khai ERP trước hội đồng và chuẩn bị hành trang ứng tuyển vào các công ty tư vấn công nghệ.'])], 'reqs': ['Đã nắm chắc kiến thức phân tích quy trình nghiệp vụ và cơ sở dữ liệu SQL.', 'Khả năng cài đặt môi trường Linux và ngôn ngữ lập trình Python cơ bản.', 'Tư duy bao quát quy trình kinh doanh và kỹ năng làm việc cẩn trọng với số liệu tài chính.']}, 'guidance-httt-y4': {'lead': 'Hướng dẫn chi tiết từ A-Z lộ trình hoạch định chiến lược chuyển đổi số, kiểm toán hệ thống thông tin và hoàn thiện khóa luận tốt nghiệp chuyên ngành hệ thống thông tin.', 'p1': 'Năm cuối cùng của chuyên ngành Hệ thống thông tin đòi hỏi sinh viên tổng hợp toàn bộ năng lực phân tích nghiệp vụ, kiến trúc công nghệ và tư duy quản trị chiến lược để giải quyết bài toán chuyển đổi số toàn diện cho doanh nghiệp. Bên cạnh đó, kiến thức về Kiểm toán hệ thống thông tin (IT Audit) và khung quản trị công nghệ thông tin (COBIT, ITIL) giúp bạn đảm bảo các hệ thống số vận hành an toàn, tuân thủ pháp luật và mang lại giá trị gia tăng tối đa.', 'p2': 'Dù định hướng trở thành Chuyên gia tư vấn chuyển đổi số, Quản lý sản phẩm (Product Manager) hay Kiểm toán viên hệ thống, việc sở hữu cái nhìn chiến lược và khả năng giải trình giá trị kinh tế của công nghệ sẽ là bệ phóng vững chắc cho sự nghiệp của bạn.', 'roles': [('Chuyên viên tư vấn chuyển đổi số (Digital Transformation Consultant)', 'Khảo sát mức độ trưởng thành số, xây dựng lộ trình số hóa và lựa chọn giải pháp công nghệ.'), ('Kiểm toán viên hệ thống thông tin tập sự (Junior IT Auditor)', 'Đánh giá các biện pháp kiểm soát chung về CNTT (ITGC), kiểm tra an toàn dữ liệu và tính tuân thủ.'), ('Chuyên viên quản lý sản phẩm số tập sự (Associate Product Manager)', 'Xác định tầm nhìn sản phẩm, quản lý vòng đời tính năng và phối hợp giữa kinh doanh và kỹ thuật.')], 'stages': [('Giai đoạn 1: Khung quản trị CNTT (COBIT/ITIL) & Chiến lược chuyển đổi số', ['Nghiên cứu khung quản trị công nghệ thông tin doanh nghiệp COBIT 2019: liên kết giữa mục tiêu chiến lược kinh doanh và mục tiêu CNTT.', 'Làm quen với khung thư viện cơ sở hạ tầng CNTT (ITIL 4): chuỗi giá trị dịch vụ, quản lý sự cố, quản lý thay đổi và quản lý mức dịch vụ (SLA).', 'Đánh giá mức độ trưởng thành số của tổ chức (Digital Maturity Assessment) trên các trụ cột: Con người, Quy trình, Công nghệ và Dữ liệu.', 'Xây dựng đề xuất lộ trình chuyển đổi số 3 năm cho một doanh nghiệp dịch vụ cụ thể kèm bảng phân tích chi phí - lợi ích (Cost-Benefit Analysis).']), ('Giai đoạn 2: Kiểm toán hệ thống thông tin (IT Audit) & Kiểm soát nội bộ', ['Hiểu rõ phương pháp luận kiểm toán hệ thống thông tin theo chuẩn CISA của ISACA.', 'Thực hiện kiểm tra các biện pháp kiểm soát chung CNTT (IT General Controls - ITGC): quản lý truy cập người dùng, quản lý thay đổi phần mềm và sao lưu dự phòng phục hồi thảm họa (Disaster Recovery).', 'Đánh giá các biện pháp kiểm soát ứng dụng tự động (Application Controls) trong việc ngăn chặn sai sót nhập liệu và gian lận giao dịch.', 'Soạn thảo báo cáo phát hiện kiểm toán (Audit Finding Report) kèm theo các khuyến nghị khắc phục rủi ro có tính khả thi cao.']), ('Giai đoạn 3: Triển khai khóa luận tốt nghiệp hệ thống thông tin ứng dụng', ['Lựa chọn đề tài khóa luận gắn liền với bài toán số hóa thực tế tại một doanh nghiệp đối tác hoặc cơ quan hành chính.', 'Thực hiện khảo sát chuyên sâu, phân tích quy trình To-Be, thiết kế kiến trúc thông tin tổng thể và hiện thực hóa bản thử nghiệm (POC).', 'Đánh giá tác động định lượng của giải pháp mới: tỷ lệ tự động hóa quy trình, thời gian xử lý hồ sơ giảm và mức độ hài lòng của nhân viên.', 'Hoàn thành toàn bộ báo cáo khóa luận tốt nghiệp theo cấu trúc học thuật chặt chẽ và chuẩn bị bộ sản phẩm nghiệm thu.']), ('Giai đoạn 4: Hoàn thiện hồ sơ năng lực, luyện phỏng vấn chiến lược & Tuyển dụng', ['Đóng gói Portfolio chuyên môn: tổng hợp các đề án tư vấn chuyển đổi số, tài liệu SRS và báo cáo kiểm toán mẫu.', 'Rèn luyện kỹ năng giải quyết tình huống kinh doanh phức tạp (Case Study Presentation) trong các kỳ tuyển dụng Management Trainee.', 'Chuẩn bị kiến thức nền tảng để sẵn sàng thi chứng chỉ quốc tế khởi đầu: chứng chỉ CAPM của PMI hoặc chứng chỉ Fundamentals của ISACA.', 'Ứng tuyển vào các công ty kiểm toán Big 4, tập đoàn tư vấn chiến lược hoặc khối công nghệ của các ngân hàng thương mại lớn.'])], 'reqs': ['Tích lũy đầy đủ kiến thức về phân tích hệ thống, cơ sở dữ liệu và quản trị kinh doanh.', 'Tư duy chiến lược, năng lực phân tích tài chính và khả năng giải quyết vấn đề cấp quản lý.', 'Khả năng trình bày thuyết phục và tác phong làm việc chuẩn mực của một nhà tư vấn.']}}
